package com.vayvora.callservice.engine.dto;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.Map;

/** Agent reply for one turn, grounded through RAG and generated by the LLM. */
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@JsonIgnoreProperties(ignoreUnknown = true)
public class EngineTurnResponse {
    @JsonProperty("session_id")
    private String sessionId;

    @JsonProperty("response_text")
    private String responseText;

    @JsonProperty("latency_ms")
    private Double latencyMs;

    /**
     * Intent, stage, citations and timing. The documented layout is flat
     * ({@code detected_intent}, {@code stage}, {@code citations}); the live
     * engine nests it ({@code intent.current_intent},
     * {@code session.conversation_stage}, {@code rag.grounded_citations}),
     * so it is passed through unchanged.
     */
    private Map<String, Object> diagnostics;
}
